'use strict';
const missions = [
 {word:'WHO',ms:'Siapa?',place:'Kaunter Aduan',x:23,y:21,speaker:'PENGADU',title:'Siapa di sebalik aduan?',story:'“Saya dengar seorang pegawai kanan menerima imbuhan daripada pembekal. Saya belum berikan nama mereka dalam aduan.”',question:'Apakah soalan susulan yang paling membantu mengenal pasti pihak terlibat?',options:['Apakah nama, jawatan pegawai, identiti pembekal dan saksi yang boleh dihubungi?','Adakah pegawai kanan itu popular dalam kalangan kakitangan?','Bolehkah kita anggap semua pegawai kanan terlibat?'],answer:0,explain:'WHO mengenal pasti pegawai, pemberi atau penerima imbuhan, pembekal serta saksi. Jawatan umum sahaja belum cukup untuk semakan yang khusus.',clue:'Pengadu menamakan Encik R, pegawai kanan perolehan, dan Syarikat M. Puan S dikatakan berada berhampiran. Identiti serta peranan mereka masih perlu disahkan.'},
 {word:'WHAT',ms:'Apa?',place:'Meja Temu Bual',x:77,y:21,speaker:'PENGADU',title:'Apakah yang dimaksudkan dengan imbuhan?',story:'“Saya gunakan perkataan imbuhan, tetapi belum terangkan bentuk atau nilainya.”',question:'Maklumat apakah yang patut diperincikan?',options:['Kesimpulan bahawa pegawai itu pasti bersalah.','Warna pakaian pegawai pada hari tersebut sahaja.','Bentuk imbuhan, anggaran nilai dan urusan yang berkaitan.'],answer:2,explain:'WHAT menjelaskan perbuatan yang diadukan, bentuk dan nilai imbuhan serta perkara berkaitan. Istilah “imbuhan” perlu diperincikan sebelum maklumat dinilai.',clue:'Menurut pengadu, imbuhan itu dikatakan wang tunai RM2,000 dalam sampul, berkaitan urusan bekalan pejabat. Nilai itu belum disahkan.'},
 {word:'WHEN',ms:'Bila?',place:'Ruang Kronologi',x:23,y:50,speaker:'PENGADU',title:'Bina garis masa kejadian.',story:'“Saya ingat kejadian berlaku selepas satu mesyuarat, tetapi tarikh dan masa belum dicatat.”',question:'Soalan manakah membantu semakan kronologi?',options:['Mengapa pengadu tidak membuat laporan lebih awal sahaja?','Bilakah tarikh dan anggaran masa, serta adakah kejadian sekali atau berulang?','Bolehkah kita pilih mana-mana tarikh mesyuarat sebagai tarikh kejadian?'],answer:1,explain:'WHEN merangkumi tarikh, masa dan kekerapan. Anggaran mesti dilabel sebagai anggaran dan disemak dengan rekod yang berkaitan.',clue:'Pengadu menganggarkan 3 September 2026, sekitar 3 petang, selepas mesyuarat pembekal. Beliau hanya mengetahui satu kejadian.'},
 {word:'WHERE',ms:'Di mana?',place:'Semakan Lokasi',x:77,y:50,speaker:'PENGADU',title:'Tentukan lokasi yang boleh disemak.',story:'“Ia berlaku di pejabat. Saya boleh terangkan lokasi dengan lebih khusus.”',question:'Apakah maklumat lokasi yang paling berguna?',options:['Bangunan, aras dan ruang tepat pemberian atau penerimaan dikatakan berlaku.','Alamat rumah semua pekerja tanpa kaitan dengan aduan.','Lokasi ibu pejabat pembekal sahaja walaupun kejadian berlaku di tempat lain.'],answer:0,explain:'WHERE memerlukan lokasi kejadian yang khusus untuk membolehkan semakan, contohnya melalui rekod akses atau rakaman yang tersedia.',clue:'Lokasi yang dinyatakan ialah koridor luar Bilik Mesyuarat B, Aras 2. Kewujudan rakaman atau rekod akses perlu disemak.'},
 {word:'WHY',ms:'Mengapa?',place:'Fail Perolehan',x:23,y:79,speaker:'PEGAWAI PENYEMAK',title:'Apakah kaitannya dengan urusan rasmi?',story:'“Pembekal mempunyai urusan bekalan pejabat. Namun, tujuan pemberian itu belum jelas.”',question:'Bagaimana anda mendapatkan maklumat WHY tanpa membuat andaian?',options:['Anggap setiap pemberian daripada pembekal membuktikan kesalahan.','Minta pengadu meneka motif jika beliau tidak mengetahuinya.','Tanya tujuan yang diketahui, kaitan dengan kontrak atau keputusan, dan asas pengetahuan itu.'],answer:2,explain:'WHY meneliti tujuan serta kaitan dengan urusan rasmi. Bezakan apa yang diketahui daripada sangkaan. Motif yang belum diketahui perlu disahkan.',clue:'Pengadu mengaitkannya dengan urusan bekalan yang sedang diproses, tetapi tidak mengetahui tujuan sebenar pemberian. Kaitan dengan keputusan rasmi belum disahkan.'},
 {word:'HOW',ms:'Bagaimana?',place:'Ruang Saksi',x:77,y:79,speaker:'PENGADU',title:'Bezakan pemerhatian dengan cerita orang.',story:'“Saya nampak sampul bertukar tangan. Tentang wang RM2,000, saya diberitahu oleh orang lain.”',question:'Apakah yang paling penting untuk dijelaskan?',options:['Menganggap isi sampul sudah terbukti kerana pengadu melihat sampul.','Cara penyerahan, apa yang dilihat sendiri dan siapa sumber maklumat tentang isi sampul.','Bilangan orang yang berkongsi khabar itu sebagai bukti bahawa ia benar.'],answer:1,explain:'HOW merangkumi cara imbuhan diberikan dan bagaimana pengadu mengetahui perkara itu. Melihat sampul tidak mengesahkan isi atau tujuannya.',clue:'Pengadu melihat penyerahan sampul secara bersemuka, tetapi tidak melihat isinya. Dakwaan RM2,000 datang daripada pihak lain yang perlu dikenal pasti dan disemak.'},
 {word:'BUKTI',place:'Meja Pengesahan',speaker:'KETUA UNIT',title:'Petunjuk memerlukan pengesahan.',story:'“Kita sudah ada butiran 5W1H, tetapi isi sampul, nilai wang dan tujuan masih belum disahkan.”',question:'Apakah langkah pengesahan yang paling sesuai?',options:['Minta bukti tersedia seperti mesej, dokumen urusan dan saksi; semak sumber serta kesesuaiannya dengan kronologi.','Anggap penyerahan sampul sebagai bukti muktamad penerimaan wang.','Abaikan maklumat pengadu kerana beliau tidak memiliki rekod bank.'],answer:0,explain:'Bukti yang tersedia boleh termasuk e-mel, WhatsApp, gambar, rakaman, invois, rekod pembayaran, kontrak dan saksi. Nilai sumber dan hubungannya dengan dakwaan. Tidak semua bukti mesti dimiliki pengadu.',clue:'Pelan pengesahan: minta mesej atau dokumen yang pengadu miliki, semak rekod mesyuarat dan urusan pembekal, serta dapatkan penjelasan saksi. Belum ada bukti muktamad tentang isi sampul.'},
 {word:'KEPUTUSAN 1',place:'Bilik Ketua Unit',speaker:'KETUA UNIT',title:'Kembali kepada aduan asal.',story:'Senario A: Anda hanya menerima ayat asal tentang “seorang pegawai kanan” dan “pembekal”, tanpa butiran lain.',question:'Mengikut rangka jawapan kumpulan, apakah tindakan yang sesuai?',options:['Terus kembangkan siasatan dengan mengandaikan identiti pegawai.','Tolak aduan sebagai palsu kerana maklumat belum lengkap.','Dapatkan maklumat tambahan daripada pengadu kerana aduan terlalu umum untuk dikembangkan.'],answer:2,explain:'Maklumat terlalu umum belum memberi asas khusus untuk dikembangkan. Dapatkan penjelasan 5W1H. Kekurangan maklumat tidak dengan sendirinya membuktikan aduan palsu.',clue:'Terlalu umum: dapatkan maklumat tambahan sebelum pengembangan.'},
 {word:'KEPUTUSAN 2',place:'Bilik Ketua Unit',speaker:'KETUA UNIT',title:'Nilai fail yang anda kumpulkan.',story:'Senario B: Pegawai, pembekal, masa, lokasi dan penyerahan sampul sudah diperincikan. Namun, isi sampul, nilai serta tujuan masih berdasarkan maklumat yang belum disahkan.',question:'Apakah cadangan tindakan terhadap fail ini?',options:['Tentukan pegawai bersalah kerana semua ruang 5W1H telah diisi.','Daftarkan aduan dan buat pengesahan lanjut melalui dokumen, rekod atau temu bual.','Hentikan semua semakan sehingga pengadu membawa bukti lengkap.'],answer:1,explain:'Maklumat sebahagian dengan petunjuk boleh didaftarkan dan memerlukan pengesahan lanjut, seperti rangka jawapan kumpulan. Ruang 5W1H yang terisi tidak menjamin dakwaan benar.',clue:'Sebahagian dengan petunjuk: daftar dan sahkan maklumat lanjut.'},
 {word:'KEPUTUSAN 3',place:'Bilik Ketua Unit',speaker:'KETUA UNIT',title:'Apabila maklumat dan bukti awal mencukupi.',story:'Senario C (andaian baharu): Butiran utama aduan lengkap. Dokumen berkaitan dan keterangan saksi memberi sokongan awal yang konsisten kepada dakwaan.',question:'Apakah keputusan yang paling sesuai?',options:['Daftarkan dan kembangkan untuk semakan atau siasatan lanjut, tanpa menganggap kesalahan sudah terbukti.','Jatuhkan hukuman serta-merta kerana maklumat lengkap.','Abaikan bukti awal dan ulang semula semua pertanyaan tanpa tujuan.'],answer:0,explain:'Maklumat lengkap dengan bukti awal membolehkan aduan didaftarkan dan dikembangkan untuk semakan atau siasatan lanjut. Kelengkapan menyokong penilaian objektif; ia bukan pengesahan kesalahan.',clue:'Lengkap dengan bukti awal: daftar dan kembangkan untuk tindakan lanjut.'}
];
const $=id=>document.getElementById(id);
let progress=0, score=0, attempted=new Set(), correctFirst=[], moving=false, current=-1;
const quiz=$('quiz');
function render(){
 $('score').textContent=score;$('collected').textContent=`${Math.min(progress,6)} / 6`;$('map-progress').textContent=`${Math.min(progress,6)} / 6 MAKLUMAT`;
 $('stations').innerHTML=missions.slice(0,6).map((m,i)=>`<button class="station ${i<progress?'done':i===progress?'active':'locked'}" style="left:${m.x}%;top:${m.y}%" data-station="${i}" ${i>progress?'disabled':''} aria-label="${m.word} ${m.ms}, ${m.place}${i>progress?', belum dibuka':i<progress?', selesai':''}"><span class="number">${i<progress?'✓':String(i+1).padStart(2,'0')}</span><span class="concept">${m.word}</span><small>${m.place}</small></button>`).join('');
 document.querySelectorAll('[data-station]').forEach(el=>el.onclick=()=>visit(Number(el.dataset.station)));
 $('notebook').innerHTML=missions.slice(0,6).map((m,i)=>`<details class="note ${i<progress?'complete':''}"><summary><span class="check">${i<progress?'✓':'○'}</span><span class="note-word">${m.word}</span><span class="note-status">${i<progress?'Diperoleh +':m.ms}</span></summary><p>${i<progress?m.clue:'Maklumat belum diperoleh. Lengkapkan lokasi ini untuk membuka catatan.'}</p></details>`).join('');
 const chapter=progress<6?['BAB 01 / LENGKAPKAN 5W1H','Cari fakta. Sambungkan cerita.']:progress===6?['BAB 02 / NILAI BUKTI','Setiap petunjuk perlu disemak.']:progress<10?['BAB 03 / KEPUTUSAN UNIT','Apakah tindakan yang wajar?']:['MISI SELESAI / FAIL 001','Maklumat dinilai. Keputusan dibuat.'];
 if(progress>0){$('chapter').textContent=chapter[0];$('headline').textContent=chapter[1];}
 $('objective').textContent=progress<6?'Temui pengadu dan lengkapkan enam unsur maklumat.':progress===6?'Bezakan dakwaan, pemerhatian sendiri dan bukti sokongan.':progress<10?'Nilai tiga tahap kelengkapan maklumat sebelum menentukan tindakan.':'Semak markah dan rumusan pembelajaran anda.';
 $('next-label').textContent=progress<10?'MISI SETERUSNYA':'LAPORAN AKHIR';
 $('next-text').textContent=progress<6?`Pergi ke ${missions[progress].place}.`:progress===6?'Semak bukti di Meja Pengesahan.':progress<10?`Bentangkan ${missions[progress].word.toLowerCase()} kepada ketua unit.`:'Kesemua 10 cabaran telah diselesaikan.';
 $('continue').innerHTML=(progress<6?'Pergi ke lokasi':progress===6?'Semak bukti':progress<10?'Buat keputusan':'Lihat keputusan')+' <span>↗</span>';
}
function visit(i){if(moving||i>progress)return;if(i<progress){showReview(i);return;}moving=true;const m=missions[i];$('avatar').classList.add('walking');$('avatar').style.left=(m.x===23?42:58)+'%';$('avatar').style.top=m.y+'%';$('location').textContent=m.place;$('continue').disabled=true;setTimeout(()=>{$('avatar').classList.remove('walking');moving=false;$('continue').disabled=false;showQuestion(i);},700);}
function showQuestion(i){current=i;const m=missions[i];$('dialog-tag').textContent=`CABARAN ${String(i+1).padStart(2,'0')} / 10 · ${m.word}`;$('dialog-content').innerHTML=`<div class="speaker">${m.speaker}</div><h2 id="dialog-title">${m.title}</h2><p class="story">${m.story}</p><div class="question">${m.question}</div><div class="choices">${m.options.map((a,n)=>`<button class="choice" data-choice="${n}"><span class="letter">${'ABC'[n]}</span><span>${a}</span></button>`).join('')}</div><div id="feedback" aria-live="polite"></div><p class="dialog-caption">${attempted.has(i)?'Cubaan semula untuk pembelajaran · tiada markah tambahan':'10 markah untuk jawapan pertama yang tepat'}</p>`;quiz.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>answer(i,Number(el.dataset.choice)));if(!quiz.open)quiz.showModal();}
function answer(i,n){const m=missions[i],first=!attempted.has(i);attempted.add(i);quiz.querySelectorAll('.choice').forEach(b=>b.disabled=true);const good=n===m.answer;quiz.querySelector(`[data-choice="${n}"]`).classList.add(good?'correct':'wrong');if(good){if(first){score+=10;correctFirst.push(i);}progress=i+1;render();$('feedback').innerHTML=`<div class="feedback"><h3>${first?'Tepat. +10 markah':'Tepat. Teruskan pembelajaran.'}</h3><p>${m.explain}</p></div><div class="speaker">${i<6?'MAKLUMAT DIPEROLEH':i===6?'PELAN PENGESAHAN':'CATATAN KEPUTUSAN'}</div><p>${m.clue}</p><button id="next-question" class="primary">${i===9?'Lihat laporan misi':'Simpan & teruskan'} <span>↗</span></button>`;$('next-question').onclick=()=>{quiz.close();if(progress===10)showResults();};}else{$('feedback').innerHTML=`<div class="feedback wrong"><h3>Belum tepat. Semak semula prinsipnya.</h3><p>${m.explain}</p></div><button id="retry" class="primary">Cuba semula <span>↻</span></button>`;$('retry').onclick=()=>showQuestion(i);} $('feedback').scrollIntoView({block:'nearest',behavior:'smooth'});}
function showReview(i){const m=missions[i];$('dialog-tag').textContent='BUKU CATATAN / '+m.word;$('dialog-content').innerHTML=`<h2 id="dialog-title">${m.ms} ${m.place}</h2><p>${m.clue}</p><div class="feedback"><h3>Prinsip ${m.word}</h3><p>${m.explain}</p></div><button class="primary" id="back-map">Kembali ke peta</button>`;$('back-map').onclick=()=>quiz.close();quiz.showModal();}
function showResults(){const rank=score>=80?'Penilai maklumat cemerlang':score>=50?'Asas kukuh, teruskan latihan':'Misi lengkap. Kukuhkan kefahaman.';$('dialog-tag').textContent='LAPORAN MISI / KUMPULAN 1';$('dialog-content').innerHTML=`<h2 id="dialog-title">${rank}</h2><div class="result-score">${score}<small> / 100</small></div><p>Anda melengkapkan semua 10 cabaran dan menyediakan cadangan tindakan terhadap aduan.</p><div class="result-grid"><div><span>TEPAT PADA CUBAAN PERTAMA</span><b>${correctFirst.length} / 10</b></div><div><span>MAKLUMAT DIKUMPUL</span><b>6 / 6 unsur</b></div></div><h3>Tiga keputusan utama</h3><ol class="result-list"><li><b>Terlalu umum:</b> dapatkan maklumat tambahan sebelum aduan dikembangkan.</li><li><b>Sebahagian dengan petunjuk:</b> daftarkan dan lakukan pengesahan lanjut.</li><li><b>Lengkap dengan bukti awal:</b> daftarkan dan kembangkan untuk semakan atau siasatan lanjut.</li></ol><div class="feedback"><h3>Maklumat lengkap ≠ dakwaan terbukti benar</h3><p>5W1H membolehkan penilaian yang khusus dan objektif. Sumber, bukti dan maklumat masih perlu disahkan.</p></div><button id="review-all" class="primary">Semak semua jawapan <span>↗</span></button><button id="restart" class="secondary">Main semula dari awal</button>`;$('restart').onclick=restart;$('review-all').onclick=showAll;if(!quiz.open)quiz.showModal();}
function showAll(){$('dialog-tag').textContent='ULANG KAJI / 10 CABARAN';$('dialog-content').innerHTML='<h2 id="dialog-title">Rumusan jawapan misi</h2>'+missions.map((m,i)=>`<div class="review-block"><h3>${String(i+1).padStart(2,'0')} · ${m.word} ${correctFirst.includes(i)?'✓ +10':'· latihan'}</h3><p>${m.question}</p><p class="review-answer">${m.options[m.answer]}</p><p>${m.explain}</p></div>`).join('')+'<button id="result-back" class="primary">Kembali ke laporan</button>';$('result-back').onclick=showResults;quiz.scrollTop=0;}
function restart(){progress=0;score=0;attempted=new Set();correctFirst=[];current=-1;quiz.close();$('avatar').style.left='50%';$('avatar').style.top='87%';$('location').textContent='Lobi utama';$('chapter').textContent='BAB 01 / ADUAN DITERIMA';$('headline').textContent='Satu aduan. Banyak persoalan.';render();$('intro').showModal();}
$('continue').onclick=()=>{if(progress<6)visit(progress);else if(progress<10){$('location').textContent=missions[progress].place;showQuestion(progress);}else showResults();};
$('close-dialog').onclick=()=>quiz.close();$('start').onclick=()=>$('intro').close();$('help').onclick=()=>$('intro').showModal();
render();$('intro').showModal();
